sealed trait TokenType {
  def name: String
}

object TokenType {
  case object STRING extends TokenType {
    override def name: String = "STRING"
  }
  case object NUMERIC extends TokenType {
    override def name: String = "NUMERIC"
  }
  case object TEMPORAL extends TokenType {
    override def name: String = "TEMPORAL"
  }
  case object WHITESPACE extends TokenType {
    override def name: String = "WHITESPACE"
  }
  case object UNKNOWN extends TokenType {
    override def name: String = "UNKNOWN"
  }
}

/**
 * Case class representing a single token with metadata
 */
case class Token(
  value: String,
  tokenType: TokenType,
  position: Int,
  metadata: Map[String, String] = Map.empty
) {
  /**
   * Add metadata to this token
   */
  def withMetadata(key: String, value: String): Token =
    this.copy(metadata = metadata + (key -> value))

  /**
   * Add multiple metadata entries
   */
  def withMetadata(newMetadata: Map[String, String]): Token =
    this.copy(metadata = metadata ++ newMetadata)
}

/**
 * Base trait for all tokenizers
 */
sealed trait BaseTokenizer {
  /**
   * Tokenize a single string value
   */
  def tokenize(value: String): Option[Token]

  /**
