      Some(Token(value, tokenType, 0))
    } else {
      None
    }
  }
}

/**
 * Tokenizer for numeric values
 */
class NumericTokenizer extends BaseTokenizer {
  override def tokenType: TokenType = TokenType.NUMERIC

  override def tokenize(value: String): Option[Token] = {
    Try {
      BigDecimal(value)
      Token(value, tokenType, 0)
    }.toOption
  }
}

/**
