/**
 * Sealed trait representing different token types
 */
sealed trait TokenType {
  def name: String
}

object TokenType {
  case object String extends TokenType {
    override def name: String = "string"
  }
  case object Numeric extends TokenType {
    override def name: String = "numeric"
  }
  case object Temporal extends TokenType {
    override def name: String = "temporal"
  }
  case object Structured extends TokenType {
    override def name: String = "structured"
  }
  case object Binary extends TokenType {
    override def name: String = "binary"
  }
  case object Null extends TokenType {
    override def name: String = "null"
  }
}

/**
 * Immutable token representation with metadata support
 */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata
   */
  def withMetadata(key: String, value: Any): Token =
    this.copy(metadata = metadata + (key -> value))

  /**
   * Return new token with multiple metadata entries
   */
  def withMetadata(newMetadata: Map[String, Any]): Token =
    this.copy(metadata = metadata ++ newMetadata)
}

/**
 * Mutable batch of tokens - contrast with immutable Token
 */
class MutableTokenBatch {
  private val tokens: mutable.ListBuffer[Token] = mutable.ListBuffer.empty
  private var processed: Boolean = false

  def add(token: Token): Unit = {
    if (processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens += token
  }

  def getAll: List[Token] = tokens.toList

  def markProcessed(): Unit = {
    processed = true
  }
}

/**
 * Base trait for all tokenizers
 */
sealed trait BaseTokenizer[T] {
  /**
   * Convert value to token
   */
  def tokenize(value: T): Option[Token]

  /**
   * Tokenize multiple values
   */
  def tokenizeBatch(values: Iterable[T]): List[Token] =
    values.flatMap(tokenize).toList
}

/**
 * String tokenizer implementation
 */
class StringTokenizer extends BaseTokenizer[String] {
  override def tokenize(value: String): Option[Token] = {
    if (value.nonEmpty) {
      Some(Token(value, TokenType.String))
    } else {
      None
    }
  }
}

/**
 * Numeric tokenizer implementation
 */
class NumericTokenizer extends BaseTokenizer[String] {
  override def tokenize(value: String): Option[Token] = {
    Try(BigDecimal(value)).toOption.map(_ =>
      Token(value, TokenType.Numeric)
    )
  }
}

/**
 * Temporal tokenizer for date/time values
 */
class TemporalTokenizer(
  dateFormats: List[DateTimeFormatter] = TemporalTokenizer.defaultFormats
) extends BaseTokenizer[String] {
  override def tokenize(value: String): Option[Token] = {
    dateFormats
      .view
      .flatMap { formatter =>
        Try(LocalDateTime.parse(value, formatter)).toOption
      }
      .headOption
      .map(_ => Token(value, TokenType.Temporal))
  }
}

object TemporalTokenizer {
  val defaultFormats: List[DateTimeFormatter] = List(
    DateTimeFormatter.ISO_DATE_TIME,
    DateTimeFormatter.ISO_DATE,
    DateTimeFormatter.ISO_TIME
  )
}

/**
 * Whitespace tokenizer for text processing
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) extends BaseTokenizer[String] {
  private val punctuationChars: String = ".,!?;:'\"()[]{}"

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(c => punctuationChars.contains(c))
        .reverse.dropWhile(c => punctuationChars.contains(c)).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      None
    } else if (maxLength.exists(processed.length > _)) {
      Some(processed.take(maxLength.get))
    } else {
      Some(processed)
    }
  }

  override def tokenize(value: String): Option[Token] = {
    processToken(value).map(Token(_, TokenType.String))
  }

  def tokenizeText(text: String): List[Token] = {
    text.split("\\s+")
      .zipWithIndex
      .flatMap { case (word, index) =>
        processToken(word).map { processed =>
          Token(
            processed,
            TokenType.String,
            Map("position" -> index, "original" -> word)
          )
        }
      }
      .toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenizeText(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer[(String, Int, Int)]()
    var currentPos = 0

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }
      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int =
    tokenizeText(text).length
