import scala.util.{Try, Success, Failure}
import scala.collection.mutable
import scala.math.BigDecimal
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/**
 * Sealed trait representing different token types
 */
sealed trait TokenType {
  def name: String
}

object TokenType {
  case object STRING extends TokenType {
    override def name: String = "STRING"
  }
  case object NUMERIC extends TokenType {
    override def name: String = "NUMERIC"
  }
  case object TEMPORAL extends TokenType {
    override def name: String = "TEMPORAL"
  }
  case object WHITESPACE extends TokenType {
    override def name: String = "WHITESPACE"
  }
  case object UNKNOWN extends TokenType {
    override def name: String = "UNKNOWN"
  }
}

/**
 * Case class representing a single token with metadata
 */
case class Token(
  value: String,
  tokenType: TokenType,
  position: Int,
  metadata: Map[String, String] = Map.empty
) {
  /**
   * Add metadata to this token
   */
  def withMetadata(key: String, value: String): Token =
    this.copy(metadata = metadata + (key -> value))

  /**
   * Add multiple metadata entries
   */
  def withMetadata(newMetadata: Map[String, String]): Token =
    this.copy(metadata = metadata ++ newMetadata)
}

/**
 * Base trait for all tokenizers
 */
sealed trait BaseTokenizer {
  /**
   * Tokenize a single string value
   */
  def tokenize(value: String): Option[Token]

  /**
   * Get the token type this tokenizer produces
   */
  def tokenType: TokenType
}

/**
 * Tokenizer for string values
 */
class StringTokenizer extends BaseTokenizer {
  override def tokenType: TokenType = TokenType.STRING

  override def tokenize(value: String): Option[Token] = {
    if (value.nonEmpty) {
      Some(Token(value, tokenType, 0))
    } else {
      None
    }
  }
}

/**
 * Tokenizer for numeric values
 */
class NumericTokenizer extends BaseTokenizer {
  override def tokenType: TokenType = TokenType.NUMERIC

  override def tokenize(value: String): Option[Token] = {
    Try {
      BigDecimal(value)
      Token(value, tokenType, 0)
    }.toOption
  }
}

/**
 * Tokenizer for temporal (date/time) values
 */
class TemporalTokenizer(
  private val dateFormats: List[DateTimeFormatter] = TemporalTokenizer.defaultFormats
) extends BaseTokenizer {
  override def tokenType: TokenType = TokenType.TEMPORAL

  override def tokenize(value: String): Option[Token] = {
    dateFormats
      .view
      .flatMap { formatter =>
        Try(LocalDateTime.parse(value, formatter)).toOption
      }
      .headOption
      .map(_ => Token(value, tokenType, 0))
  }
}

object TemporalTokenizer {
  val defaultFormats: List[DateTimeFormatter] = List(
    DateTimeFormatter.ISO_DATE_TIME,
    DateTimeFormatter.ISO_DATE,
    DateTimeFormatter.ISO_TIME
  )
}

/**
 * Tokenizer for whitespace
 */
