 */
class MutableTokenBatch {
  private val tokens: mutable.ListBuffer[Token] = mutable.ListBuffer.empty
  private var processed: Boolean = false

  def add(token: Token): Unit = {
    if (processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens += token
  }

  def getAll: List[Token] = tokens.toList

  def markProcessed(): Unit = {
    processed = true
  }
}

/**
 * Base trait for all tokenizers
 */
sealed trait BaseTokenizer[T] {
  /**
   * Convert value to token
   */
  def tokenize(value: T): Option[Token]

  /**
   * Tokenize multiple values
   */
  def tokenizeBatch(values: Iterable[T]): List[Token] =
    values.flatMap(tokenize).toList
}

/**
 * String tokenizer implementation
 */
class StringTokenizer extends BaseTokenizer[String] {
  override def tokenize(value: String): Option[Token] = {
    if (value.nonEmpty) {
      Some(Token(value, TokenType.String))
    } else {
      None
    }
  }
}

/**
 * Numeric tokenizer implementation
 */
class NumericTokenizer extends BaseTokenizer[String] {
  override def tokenize(value: String): Option[Token] = {
    Try(BigDecimal(value)).toOption.map(_ =>
      Token(value, TokenType.Numeric)
