/**
 * Whitespace tokenizer for text processing
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) extends BaseTokenizer[String] {
  private val punctuationChars: String = ".,!?;:'\"()[]{}"

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(c => punctuationChars.contains(c))
        .reverse.dropWhile(c => punctuationChars.contains(c)).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      None
    } else if (maxLength.exists(processed.length > _)) {
      Some(processed.take(maxLength.get))
    } else {
      Some(processed)
    }
  }

  override def tokenize(value: String): Option[Token] = {
    processToken(value).map(Token(_, TokenType.String))
  }

  def tokenizeText(text: String): List[Token] = {
    text.split("\\s+")
      .zipWithIndex
      .flatMap { case (word, index) =>
        processToken(word).map { processed =>
          Token(
            processed,
            TokenType.String,
            Map("position" -> index, "original" -> word)
          )
        }
      }
      .toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenizeText(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer[(String, Int, Int)]()
    var currentPos = 0

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }
      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int =
    tokenizeText(text).length
}

