) extends BaseTokenizer[String] {
  override def tokenize(value: String): Option[Token] = {
    tokenizers
      .view
      .flatMap(_.tokenize(value))
      .headOption
      .orElse(Some(Token(value, TokenType.Null)))
  }

  def tokenizeWith(
    customTokenizers: List[BaseTokenizer[String]]
  )(value: String): Option[Token] = {
    customTokenizers
      .view
      .flatMap(_.tokenize(value))
      .headOption
      .orElse(Some(Token(value, TokenType.Null)))
  }
}

