class TokenizerBuilder {
  private val normalizers: mutable.ListBuffer[String => String] = mutable.ListBuffer.empty
  private val validators: mutable.ListBuffer[String => Boolean] = mutable.ListBuffer.empty
  private val metadata: mutable.Map[String, Any] = mutable.Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: String => Boolean): TokenizerBuilder = {
    validators += validator
    this
  }

  def withMetadata(key: String, value: Any): TokenizerBuilder = {
    metadata(key) = value
    this
  }

  def withMetadata(entries: Map[String, Any]): TokenizerBuilder = {
    metadata ++= entries
    this
  }

  def build(): String => Token = {
    val normalizersList = normalizers.toList
    val validatorsList = validators.toList
    val metadataMap = metadata.toMap

    (value: String) => {
      validatorsList.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
